// On a phone (or any card narrower than its actions), a labelled Button
// shrinks with its row and truncates its label with an ellipsis instead of
// overflowing or being clipped by the card. The full label stays the
// accessible name. Icon-only buttons keep their square size.
function ReviewersCard() {
  const [emails, setEmails] = useState('');
  return (
    <Card maxWidth={560}>
      <VStack gap={4}>
        <HStack gap={2} vAlign="center">
          <StackItem size="fill">
            <Heading level={3} maxLines={1}>
              Design review
            </Heading>
          </StackItem>
          <Button label="Request review from the design team" size="sm" />
          <IconButton
            label="More review options"
            icon={<Icon icon="moreHorizontal" />}
            variant="ghost"
            size="sm"
          />
        </HStack>
        <TextInput
          label="Reviewer emails"
          placeholder="name@example.com"
          value={emails}
          onChange={setEmails}
        />
        {/* In a 320px form footer the long primary action truncates.
            StackItem size="static" keeps the short Cancel label whole. */}
        <HStack gap={2} hAlign="end">
          <StackItem size="static">
            <Button label="Cancel" variant="secondary" />
          </StackItem>
          <Button label="Send invitations to all 12 reviewers" variant="primary" />
        </HStack>
      </VStack>
    </Card>
  );
}

import {Button} from '@astryxdesign/core/Button';
import {
  useCalendarDays,
  useCalendarNavigation,
} from '@astryxdesign/core/Calendar';

function PersianMonth() {
  const {monthYearLabel, visibleCalendarMonths, navigateMonth} =
    useCalendarNavigation({initialValue: '2026-10-30', calendar: 'persian'});
  // visibleCalendarMonths[0] is {year: 1405, month: 8}: Aban 1405.
  const {weeks} = useCalendarDays({
    ...visibleCalendarMonths[0],
    calendar: 'persian',
  });
  return (
    <section aria-label={monthYearLabel}>
      <Button label="Previous month" onClick={() => navigateMonth(-1)} />
      <Button label="Next month" onClick={() => navigateMonth(1)} />
      {weeks.map(week => (
        <div key={week[0].iso}>
          {week.map(day => (
            <span key={day.iso} data-date={day.iso}>
              {day.isOutside ? '' : day.dayNumber}
            </span>
          ))}
        </div>
      ))}
    </section>
  );
}

